'use client';

import { useTranslation } from '@fanfanlo';
import { Box, Button } from '@mui/material';
import { useProjectSettings } from '../context/ProjectSettingsContext';

export function DeleteSection() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
  const { setDeleteConfirmOpen } = useProjectSettings();

  return (
    <Box>
      <Button
        data-testid="ProjectSettingsContent__deleteButton__01JG2B0087"
        data-test-comment="删除项目按钮"
        variant="contained"
        color="error"
        onClick={() => setDeleteConfirmOpen(true)}
      >
        {t('DeleteSection.label')}
      </Button>
    </Box>
  );
}
