'use client';

import { useTranslation } from '@fanfanlo';
import { Box, Button, CircularProgress } from '@mui/material';
import { useRouter } from 'next/router';
import { useProjectSettings } from '../context/ProjectSettingsContext';

export function ActionButtons() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
  const router = useRouter();
  const { saving, handleSave } = useProjectSettings();

  return (
    <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
      <Button
        data-testid="ProjectSettingsContent__cancelButton__01JG2B0088"
        data-test-comment="取消按钮"
        variant="outlined"
        onClick={() => router.back()}
        disabled={saving}
      >
        {t('ActionButtons.cancel')}
      </Button>
      <Button
        data-testid="ProjectSettingsContent__saveButton__01JG2B0089"
        data-test-comment="保存按钮"
        variant="contained"
        onClick={handleSave}
        disabled={saving}
      >
        {saving ? <CircularProgress size={24} /> : t('ActionButtons.save')}
      </Button>
    </Box>
  );
}
