'use client';

import { useTranslation, Log } from '@fanfanlo';
import {
  Alert,
  Box,
  CircularProgress,
  Divider,
  Stack,
} from '@mui/material';
import { useRouter } from 'next/router';
import { useProjectSettings, ProjectSettingsProvider } from './context/ProjectSettingsContext';
import { SyncToServerSection } from './components/SyncToServerSection';
import { ShareSection } from './components/ShareSection';
import { DeleteSection } from './components/DeleteSection';
import { ActionButtons } from './components/ActionButtons';
import { DeleteConfirmDialog } from './components/DeleteConfirmDialog';
import { ProjectBasicInfoSection } from './components/ProjectBasicInfoSection';

const fileLog = new Log(false, 'ProjectSettingsContent');
fileLog.pause = true;
fileLog.childrenPaused = true;
// 内部组件：主内容
function ProjectSettingsContentInner() {
  const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/content');
  const { loading, error, project, isUserLoggedIn } = useProjectSettings();

  fileLog.log('[ProjectSettingsContentInner] isUserLoggedIn:', isUserLoggedIn);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ padding: 2 }}>
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  if (!project) {
    return (
      <Box sx={{ padding: 2 }}>
        <Alert severity="error">{t('ProjectSettingsContent.projectNotFound')}</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ padding: 2 }}>
      <Stack spacing={3}>
        <ProjectBasicInfoSection />
        <Divider />
        
        {isUserLoggedIn ? (
          <>
            <SyncToServerSection />
            <Divider />
          </>
        ) : null}

        {isUserLoggedIn ? (
          <>
            <ShareSection />
            <Divider />
          </>
        ) : null}

        {/* 删除设置 */}
        <DeleteSection />

        {/* 操作按钮 */}
        <ActionButtons />
      </Stack>

      {/* 删除确认对话框 */}
      <DeleteConfirmDialog />
    </Box>
  );
}

// 导出的主组件
export function ProjectSettingsContent() {
  return (
    <ProjectSettingsProvider>
      <ProjectSettingsContentInner />
    </ProjectSettingsProvider>
  );
}
