import { Box, Typography } from '@mui/material';
import { EntityBasicInfoEditor } from '@droid/project-v2-ui';
import { useProjectSettings } from '../context/ProjectSettingsContext';
import { useTranslation } from '@fanfanlo';

export function ProjectBasicInfoSection() {
    const { t } = useTranslation('homepage/components/project/ProjectSettingsContent/components/content');
    const { project, saving } = useProjectSettings();

    if (!project) return null;

    return (
        <Box sx={{ py: 2 }}>
            <Typography variant="h6" sx={{ mb: 2 }}>
                {t('ProjectBasicInfoSection.title')}
            </Typography>
            <EntityBasicInfoEditor
                entity={project}
                showTitle={true}
                showSubtitle={true}
                showTags={true}
                showCategories={true}
                disabled={saving}
                componentName="ProjectBasicInfo"
            />
        </Box>
    );
}
