import { IRequestParams, IResultContent, request } from "@fanfanlo";
import { Log } from "@fanfanlo";
import { IRequestOptions } from "../IRequestOptions";
import { tms } from "../tms";

const fileLog = new Log(false, 'deleteProject_f');
// fileLog.pause = true;

/**
 * 删除项目的请求参数
 */
export interface IDeleteProjectParams extends IRequestParams {
    data: {
        uuid: string;  // 必填：要删除的项目 UUID
    };
}

/**
 * 删除项目的返回结果
 */
export interface IDeleteProjectResult extends IResultContent {
    is_ok: boolean;
    msg?: string;
    uuid?: string;      // 被删除的项目 UUID
    deletedAt?: number; // 删除时间戳（毫秒）
}

/**
 * 删除项目
 * @param opts 请求选项
 * @returns 删除结果
 */
export async function deleteProject(opts: IRequestOptions<IDeleteProjectParams>) {
    const fnLog = fileLog.sub(false, 'deleteProject_fn');
    // fnLog.pause = true;

    fnLog.log('[deleteProject] 开始删除项目, params:', JSON.stringify(opts.params));

    const res = await request<IDeleteProjectResult>(
        tms.TProject,
        tms.MProjectDeleteProject,
        opts.params,
        opts.gateway,
        opts.handler
    );

    fnLog.log('[deleteProject] 请求完成, shellIsOk:', res.shellIsOk, 'dataIsOk:', res.dataIsOk);

    if (!res.shellIsOk) {
        fnLog.log('[deleteProject] ERROR: 请求失败, err:', JSON.stringify(res.err));
    }

    if (!res.dataIsOk) {
        fnLog.log('[deleteProject] ERROR: 数据异常, errMsg:', res.data?.errMsg, 'errCode:', res.data?.errCode);
    }

    if (res.data) {
        if (res.data.is_ok) {
            fnLog.log('[deleteProject] 删除成功, uuid:', res.data.uuid, 'deletedAt:', res.data.deletedAt);
        } else {
            fnLog.log('[deleteProject] ERROR: 删除失败, msg:', res.data.msg);
        }
    } else {
        fnLog.log('[deleteProject] ERROR: 无返回数据');
    }

    return res;
}

export default deleteProject;
