'use client';

import { deleteProject, useUserIsLoggedIn } from '@app/model';
import { IProject, IProjectSettings, projectStore, ProjectVisibility } from '@droid/project-v2-interface';
import { Log } from '@fanfanlo';
import { useRouter } from 'next/router';
import { createContext, ReactNode, useContext, useEffect, useState } from 'react';
import toast from 'react-hot-toast';

const fileLog = new Log(false, 'ProjectSettingsContext');
fileLog.pause = true;
fileLog.childrenPaused = true;

// 类型定义
export interface ProjectSettingsContextType {
  // 状态
  project: IProject | null;
  projectSettings: IProjectSettings | null;
  loading: boolean;
  syncToServer: boolean;
  isPublic: boolean;
  deleteConfirmOpen: boolean;
  deleteFromLocal: boolean;
  deleteFromServer: boolean;
  saving: boolean;
  error: string | null;
  isUserLoggedIn: boolean;

  // 操作
  setSyncToServer: (value: boolean) => void;
  setIsPublic: (value: boolean) => void;
  setDeleteConfirmOpen: (value: boolean) => void;
  setDeleteFromLocal: (value: boolean) => void;
  setDeleteFromServer: (value: boolean) => void;
  handleSave: () => Promise<void>;
  handleDelete: () => Promise<void>;
  handleCancel: () => void;
  setError: (error: string | null) => void;
}

// 创建 Context
const ProjectSettingsContext = createContext<ProjectSettingsContextType | undefined>(undefined);

// Provider 组件
export function ProjectSettingsProvider({ children }: { children: ReactNode }) {
  const router = useRouter();

  const [isUserLoggedIn] = useUserIsLoggedIn();
  fileLog.log('[Provider] isUserLoggedIn:', isUserLoggedIn);

  // 状态管理
  const [project, setProject] = useState<IProject | null>(null);
  const [projectSettings, setProjectSettings] = useState<IProjectSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [syncToServer, setSyncToServer] = useState(false);
  const [isPublic, setIsPublic] = useState(false);
  const [deleteConfirmOpen, setDeleteConfirmOpen] = useState(false);
  const [deleteFromLocal, setDeleteFromLocal] = useState(false);
  const [deleteFromServer, setDeleteFromServer] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);



  useEffect(() => {
    const fnLog = fileLog.sub(false, 'init_useEffect_fn');
    fnLog.log('[init] useEffect 初始化');

    if (!router.isReady) {
      fnLog.log('[init] router未就绪，跳过初始化');
      return;
    }

    const projectUlid = router.query.projectUlid as string;
    fnLog.log('[init] projectUlid:', projectUlid);

    if (!projectUlid) {
      fnLog.log('[init] projectUlid为空，显示错误');
      setError('项目ID是必需的');
      setLoading(false);
      return;
    }

    try {
      fnLog.log('[init] 查找project');
      const foundProject = projectStore.findProject(projectUlid);
      fnLog.log('[init] 找到的project:', foundProject ? JSON.stringify(foundProject) : 'null');

      if (!foundProject) {
        fnLog.log('[init] project不存在');
        setError('项目未找到');
        setLoading(false);
        return;
      }

      setProject(foundProject);

      // 加载设置
      fnLog.log('[init] 加载project设置');
      const settings = projectStore.getProjectSettings(projectUlid);
      fnLog.log('[init] 加载的设置:', settings ? JSON.stringify(settings) : 'null');

      if (settings) {
        fnLog.log('[init] 设置存在，syncToServer:', settings.syncToServer);
        setProjectSettings(settings);
        setSyncToServer(settings.syncToServer);
        fnLog.log('[init] 已设置 syncToServer state:', settings.syncToServer);
      } else {
        fnLog.log('[init] 设置不存在');
      }

      // 判断是否公开
      const isPublicValue = foundProject.visibility === ProjectVisibility.Public;
      fnLog.log('[init] isPublic:', isPublicValue);
      setIsPublic(isPublicValue);

      setLoading(false);
      fnLog.log('[init] 初始化完成');
    } catch (err) {
      fnLog.log('[init] 初始化异常:', err);
      setError(err instanceof Error ? err.message : 'Unknown error');
      setLoading(false);
    }
  }, [router.isReady, router.query.projectUlid]);

  // 处理保存
  async function handleSave() {
    const fnLog = fileLog.sub(false, 'handleSave_fn');
    fnLog.log('[handleSave] 开始保存');
    fnLog.log('[handleSave] project.ulid:', project?.ulid);
    fnLog.log('[handleSave] syncToServer state:', syncToServer);

    if (!project) {
      fnLog.log('[handleSave] ERROR: project为空');
      return;
    }

    setSaving(true);
    setError(null);

    try {
      fnLog.log('[handleSave] 开始保存到 projectStore');

      // 直接从 projectStore 获取 settings
      const settings = projectStore.getProjectSettings(project.ulid!);
      fnLog.log('[handleSave] 从 projectStore 获取的 settings:', JSON.stringify(settings));

      if (settings) {
        fnLog.log('[handleSave] settings 存在', settings);
        fnLog.log('[handleSave] 旧 syncToServer:', settings.syncToServer);
        fnLog.log('[handleSave] 新 syncToServer:', syncToServer);

        // 直接修改现有对象的属性，不创建新对象
        settings.syncToServer = syncToServer;
        fnLog.log('[handleSave] 已修改 syncToServer:', settings.syncToServer);
      } else {
        fnLog.log('[handleSave] ERROR: settings 为 null');
      }

      // 如果visibility改变，需要更新project对象
      const newVisibility = isPublic ? ProjectVisibility.Public : ProjectVisibility.Private;
      if (project.visibility !== newVisibility) {
        fnLog.log('[handleSave] visibility改变');
        fnLog.log('[handleSave] 旧visibility:', project.visibility);
        fnLog.log('[handleSave] 新visibility:', newVisibility);

        // 直接修改project对象的visibility属性
        project.visibility = newVisibility;
        fnLog.log('[handleSave] 已修改project.visibility:', project.visibility);

        // TODO: 调用updateProject API来保存到服务器
        // const updateData = {
        //   uuid: project.uuid || project.ulid,
        //   visibility: newVisibility,
        // };
        // fnLog.log('[handleSave] updateData:', JSON.stringify(updateData));
      }

      fnLog.log('[handleSave] 保存成功');
      setSaving(false);

      goBack('handleSave');
    } catch (err) {
      fnLog.log('[handleSave] 保存异常:', err);
      setError(err instanceof Error ? err.message : '保存失败');
      setSaving(false);
    }
  }

  // 处理删除
  async function handleDelete() {
    const fnLog = fileLog.sub(false, 'handleDelete_fn');
    fnLog.pause = true;
    fnLog.log('[handleDelete] 开始删除');
    fnLog.log('[handleDelete] isUserLoggedIn:', isUserLoggedIn);
    fnLog.log('[handleDelete] deleteFromLocal:', deleteFromLocal);
    fnLog.log('[handleDelete] deleteFromServer:', deleteFromServer);

    if (!project) {
      fnLog.log('[handleDelete] project为空');
      return;
    }

    if (!isUserLoggedIn) {
      fnLog.log('[handleDelete] 未登录，直接删除本地项目');
      setSaving(true);
      setError(null);

      try {
        const projectUlid = project.ulid;
        fnLog.log('[handleDelete] projectUlid:', projectUlid);
        fnLog.log('[handleDelete] 删除本地project');
        projectStore.removeProject(projectUlid);
        fnLog.log('[handleDelete] 本地删除成功');
        fnLog.log('[handleDelete] 显示删除成功提示');
        toast.success('项目已删除');
        setSaving(false);
        setDeleteConfirmOpen(false);
        fnLog.log('[handleDelete] 删除成功，返回首页');
        router.replace('/');
        return;
      } catch (err) {
        fnLog.log('[handleDelete] 删除异常:', err);
        setError(err instanceof Error ? err.message : '删除失败');
        setSaving(false);
        return;
      }
    }

    if (!deleteFromLocal && !deleteFromServer) {
      fnLog.log('[handleDelete] 删除选项为空');
      return;
    }

    setSaving(true);
    setError(null);

    try {
      const projectUlid = project.ulid;
      fnLog.log('[handleDelete] projectUlid:', projectUlid);

      if (deleteFromServer) {
        fnLog.log('[handleDelete] 删除服务器端project');
        if (!project.uuid) {
          fnLog.log('[handleDelete] WARNING: project.uuid为空，跳过服务器端删除');
          fnLog.log('[handleDelete] 继续删除本地project');
        } else {
          fnLog.log('[handleDelete] 调用deleteProject API，uuid:', project.uuid);
          try {
            const deleteRes = await deleteProject({
              params: { data: { uuid: project.uuid } },
            });
            fnLog.log('[handleDelete] deleteProject API响应:', JSON.stringify(deleteRes));

            if (!deleteRes.dataIsOk || !deleteRes.data?.is_ok) {
              fnLog.log('[handleDelete] WARNING: 删除服务器端项目失败，msg:', deleteRes.data?.msg);
              fnLog.log('[handleDelete] 继续删除本地project');
            } else {
              fnLog.log('[handleDelete] 删除服务器端项目成功');
            }
          } catch (err) {
            fnLog.log('[handleDelete] WARNING: deleteProject API调用异常:', err);
            fnLog.log('[handleDelete] 继续删除本地project');
          }
        }
      }

      if (deleteFromLocal) {
        fnLog.log('[handleDelete] 删除本地project');
        projectStore.removeProject(projectUlid);
        fnLog.log('[handleDelete] 本地删除成功');
      }

      fnLog.log('[handleDelete] 删除成功');
      fnLog.log('[handleDelete] 显示删除成功提示');
      toast.success('项目已删除');
      setSaving(false);
      setDeleteConfirmOpen(false);

      // 删除成功，返回首页
      fnLog.log('[handleDelete] 删除成功，返回首页');
      router.replace('/');
    } catch (err) {
      fnLog.log('[handleDelete] 删除异常:', err);
      setError(err instanceof Error ? err.message : '删除失败');
      setSaving(false);
    }
  }

  // 公用的返回函数
  function goBack(logPrefix: string) {
    const fnLog = fileLog.sub(false, 'goBack_fn');
    fnLog.pause = true;
    fnLog.log(`[${logPrefix}] 开始返回`);

    // 返回到backPath或上一页
    const backPath = router.query.backPath as string;
    fnLog.log(`[${logPrefix}] backPath:`, backPath);

    if (backPath) {
      fnLog.log(`[${logPrefix}] 跳转到backPath`);
      router.replace(backPath)
    } else {
      fnLog.log(`[${logPrefix}] 返回上一页`);
      router.back();
    }
  }

  // 处理取消
  function handleCancel() {
    const fnLog = fileLog.sub(false, 'handleCancel_fn');
    fnLog.log('[handleCancel] 取消操作');
    goBack('handleCancel');
  }

  const value: ProjectSettingsContextType = {
    project,
    projectSettings,
    loading,
    syncToServer,
    isPublic,
    deleteConfirmOpen,
    deleteFromLocal,
    deleteFromServer,
    saving,
    error,
    isUserLoggedIn,
    setSyncToServer,
    setIsPublic,
    setDeleteConfirmOpen,
    setDeleteFromLocal,
    setDeleteFromServer,
    handleSave,
    handleDelete,
    handleCancel,
    setError,
  };

  return (
    <ProjectSettingsContext.Provider value={value}>
      {children}
    </ProjectSettingsContext.Provider>
  );
}

// 自定义 hook
export function useProjectSettings() {
  const context = useContext(ProjectSettingsContext);
  if (!context) {
    throw new Error('useProjectSettings must be used within ProjectSettingsProvider');
  }
  return context;
}
